
document.addEventListener("DOMContentLoaded",function(){var $=jQuery;const pathToServer=vkLtc.ajaxurl;const sendData={action:'ids'};const decodeUri=(url)=>{if(/%[0-9a-fA-F]{2}/.test(url)){try{return decodeURIComponent(url);}catch(error){return url;}}
return url;}
$.post(pathToServer,sendData,function(ps){if(typeof ps==='string'){try{ps=JSON.parse(ps);}catch(e){return;}}
if(!ps||typeof ps!=='object'||$.isEmptyObject(ps))return;$.each(ps,function(id,ls){if(!ls||typeof ls!=='object')return;try{var redirectUrl=ls.re||'';var permalinkUrl=ls.pl||'';if(!redirectUrl&&!permalinkUrl)return;var decodedRedirect=decodeUri(redirectUrl);var decodedPermalink=decodeUri(permalinkUrl);var targetBlank=Number(ls.tg)===1;var c=$('.post-'+id+' a').filter(function(){var href=decodeUri($(this).attr('href'));return href===decodedRedirect||href===decodedPermalink;});if(c.length){if(redirectUrl){$(c).attr('href',redirectUrl);}
$(c).attr('target',targetBlank?'_blank':'_self');if(targetBlank){$(c).each(function(){var rel=($(this).attr('rel')||'').split(/\s+/).filter(Boolean);if(rel.indexOf('noreferrer')===-1)rel.push('noreferrer');if(rel.indexOf('noopener')===-1)rel.push('noopener');$(this).attr('rel',rel.join(' '));});}else{$(c).each(function(){var rel=($(this).attr('rel')||'').split(/\s+/).filter(Boolean).filter(function(v){return v!=='noreferrer'&&v!=='noopener';}).join(' ');if(rel){$(this).attr('rel',rel);}else{$(this).removeAttr('rel');}});}
var editUrl=ls.el||'';if(editUrl){c.each(function(){if($(this).find('img').length>0){return;}
if($(this).next('.vk-ltc-edit-link').length>0){return;}
var editLabel=(vkLtc.editLabel||'Edit');var $editLink=$('<a>').addClass('vk-ltc-edit-link').attr('href',editUrl).css({'font-size':'0.75em','margin-left':'0.5em','white-space':'nowrap',}).text('['+editLabel+']');$(this).after($editLink);return false;});}}}catch(e){}});});},false);